#include "estimate.h"
#include <QStringList>

int parseEstimate(const QString &text)
{
    const QString trimmed = text.trimmed();
    if (trimmed.isEmpty())
        return -1;

    int total = 0;
    const QStringList parts = trimmed.split(' ');
    for (const QString &part : parts) {
        if (part.isEmpty())
            continue; // skip spaces between parts
        if (part.size() < 2)
            return -1; // missing number or unit

        const QString numStr = part.left(part.size() - 1);
        const QChar unit = part.back();

        int value = 0;
        if (!numStr.toInt(&value))
            return -1; // missing number
        if (value < 0)
            return -1; // negative number

        switch (unit.toLatin1()) {
        case 'w': total += value * 5 * 8 * 60; break; // 5 days of 8 hours
        case 'd': total += value * 8 * 60; break;     // 8 hours
        case 'h': total += value * 60; break;
        case 'm': total += value; break;
        default: return -1; // unknown unit
        }
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return {};

    QStringList out;
    const int weeks = minutes / (5 * 8 * 60);
    if (weeks)
        out << QString::number(weeks) + "w";

    const int afterWeeks = minutes % (5 * 8 * 60);
    const int days = afterWeeks / (8 * 60);
    if (days)
        out << QString::number(days) + "d";

    const int afterDays = afterWeeks % (8 * 60);
    const int hours = afterDays / 60;
    if (hours)
        out << QString::number(hours) + "h";

    const int mins = afterDays % 60;
    if (mins)
        out << QString::number(mins) + "m";

    if (out.isEmpty())
        out << "0m";

    return out.join(' ');
}

